import numpy as np
atoms=[]
def add(e,p): atoms.append((e,np.array(p,float))); return len(atoms)-1
def addH(c, nbrs, n):
    c=atoms[c][1]; v=sum((c-atoms[i][1])/np.linalg.norm(c-atoms[i][1]) for i in nbrs); v/=np.linalg.norm(v)
    a=np.cross(v,[0.3,0.5,0.8]); a/=np.linalg.norm(a); b=np.cross(v,a)
    if n==3:
        for k in range(3):
            t=2*np.pi*k/3; d=v*0.34+0.94*(np.cos(t)*a+np.sin(t)*b); add('H',c+1.09*d/np.linalg.norm(d))
    elif n==2:
        # perpendicular to plane
        u=[atoms[i][1]-c for i in nbrs]; p=np.cross(u[0],u[1]); p/=np.linalg.norm(p)
        for s in (1,-1):
            d=v*0.58+s*p*0.81; add('H',c+1.09*d/np.linalg.norm(d))
tc=add('Tc',[0,0,0])
for s in (1,-1):
    S=add('S',[0,0,2.40*s]); C=add('C',[1.2*s,0.6,3.4*s]); addH(C,[S],3)
r=2.45/np.sqrt(2)
for sx in (1,-1):
    Ps=[]
    for sy in (1,-1):
        P=add('P',[sx*r,sy*r,0]); Ps.append(P)
    for P in Ps:
        pp=atoms[P][1]
        for sz in (1,-1):
            C=add('C',pp+np.array([sx*0.6,np.sign(pp[1])*0.9,sz*1.4])); addH(C,[P],3)
    Cb=[]
    for P in Ps:
        pp=atoms[P][1]; C=add('C',[sx*3.1,np.sign(pp[1])*0.77,0]); Cb.append(C)
    for P,C,O in zip(Ps,Cb,Cb[::-1]): addH(C,[P,O],2)
with open('init.xyz','w') as f:
    f.write(f"{len(atoms)}\nTc(dmpe)2(SMe)2\n")
    for e,p in atoms: f.write(f"{e} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
EOF
